//! Generated byte fixtures keep their writer while each case opens its own
//! reader. Reopening a truncating writer on Windows repeats close-time native
//! filesystem work unrelated to the read, cursor and custody properties.
use std::{
    cell::RefCell,
    fs::File,
    io::{self, Seek as _, Write as _},
    path::Path,
};

pub(super) struct SourceFixture {
    file: RefCell<File>,
}

impl SourceFixture {
    pub(super) fn new(path: &Path) -> io::Result<Self> {
        Ok(Self {
            file: RefCell::new(File::options().create_new(true).write(true).open(path)?),
        })
    }

    pub(super) fn reset(&self, bytes: &[u8]) -> io::Result<()> {
        let mut file = self.file.borrow_mut();
        file.rewind()?;
        file.write_all(bytes)?;
        file.set_len(u64::try_from(bytes.len()).map_err(io::Error::other)?)
    }
}

#[test]
fn source_fixture_resets_empty_shorter_and_longer_inputs() -> io::Result<()> {
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("source");
    let source = SourceFixture::new(&path)?;
    for bytes in [
        b"".as_slice(),
        b"long original",
        b"cut",
        b"",
        b"new",
        b"longer again",
    ] {
        source.reset(bytes)?;
        assert_eq!(std::fs::read(&path)?, bytes);
    }
    // Omitting truncation leaks a previous input's tail into later cases.
    {
        let mut file = source.file.borrow_mut();
        file.rewind()?;
        file.write_all(b"cut")?;
    }
    assert_ne!(std::fs::read(&path)?, b"cut");
    source.reset(b"cut")?;
    assert_eq!(std::fs::read(&path)?, b"cut");
    Ok(())
}

#[test]
fn source_fixture_keeps_its_writer_when_the_name_is_replaced() -> io::Result<()> {
    let directory = tempfile::tempdir()?;
    let path = directory.path().join("source");
    let retained = directory.path().join("retained");
    let source = SourceFixture::new(&path)?;
    source.reset(b"original")?;
    std::fs::rename(&path, &retained)?;
    std::fs::write(&path, b"replacement")?;
    source.reset(b"next")?;
    assert_eq!(std::fs::read(&retained)?, b"next");
    assert_eq!(std::fs::read(&path)?, b"replacement");
    // The former pathname writer reaches a different file instead.
    std::fs::write(&path, b"wrong")?;
    assert_ne!(std::fs::read(&retained)?, b"wrong");
    assert_eq!(std::fs::read(&path)?, b"wrong");
    Ok(())
}
